def get_total_number_of_sequences(m, n):
    # Validate inputs
    if not isinstance(m, int) or not isinstance(n, int) or m <= 0 or n <= 0:
        raise ValueError("Inputs m and n must be positive integers.")

    # Edge case: If n == 1, every number from 1 to m is a valid sequence
    if n == 1:
        return m

    # Initialize the DP table
    # dp[i][j] represents the number of valid sequences of length i ending with j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: For sequences of length 1, all numbers from 1 to m are valid
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the DP table for sequences of length 2 to n
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # Sum up all dp[i-1][k] where k * 2 <= j
            dp[i][j] = sum(dp[i - 1][k] for k in range(1, (j // 2) + 1))

    # The result is the sum of all dp[n][j] for j in [1, m]
    return sum(dp[n][j] for j in range(1, m + 1))
